	minPixelSize: f32,
	minContribution: f32,
	foveationStrength: f32,
	foveationCenter: f32,
	viewMatrix: mat4x4f,
	viewProj: mat4x4f,
	focal: vec2f,
	viewportWidth: f32,
	viewportHeight: f32,
	nearClip: f32,
	farClip: f32,
	isOrtho: u32,
